$function$

CREATE OR REPLACE FUNCTION public.create_diary_comment(p_diary_id uuid, p_content text, p_nickname text DEFAULT NULL::text, p_parent_comment_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(comment_id uuid, awarded integer, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid     uuid := auth.uid();
  v_id      uuid;
  v_author  uuid;
  v_len     integer;
  v_claim   record;
  v_awarded integer := 0;
  v_parent  public.diary_comments%rowtype;
begin
  if v_uid is null then
    return query select null::uuid, 0, '로그인이 필요합니다'::text; return;
  end if;

  v_len := length(btrim(coalesce(p_content, '')));
  if v_len = 0 then
    return query select null::uuid, 0, '댓글을 입력해 주세요'::text; return;
  end if;
  if v_len > 500 then
    return query select null::uuid, 0, '500자 안으로 적어주세요'::text; return;
  end if;

  select d.user_id into v_author from public.diaries d
   where d.id = p_diary_id and d.status = 'visible';
  if v_author is null then
    return query select null::uuid, 0, '이미 지워진 이야기예요'::text; return;
  end if;

  -- 답글이면: 같은 글에 달린, 그 자체가 답글이 아닌(1단계) 댓글이어야 한다(2단계까지만 허용).
  if p_parent_comment_id is not null then
    select * into v_parent from public.diary_comments p
     where p.id = p_parent_comment_id and p.diary_id = p_diary_id and p.status = 'visible';
    if v_parent.id is null then
      return query select null::uuid, 0, '이미 지워진 댓글이에요'::text; return;
    end if;
    if v_parent.parent_comment_id is not null then
      return query select null::uuid, 0, '답글에는 답글을 달 수 없어요'::text; return;
    end if;
  end if;

  insert into public.diary_comments (diary_id, user_id, nickname, content, parent_comment_id)
  values (p_diary_id, v_uid, p_nickname, btrim(p_content), p_parent_comment_id)
  returning id into v_id;

  -- 적립 조건: 남의 글 + 5자 이상 + 이 글에서 아직 받은 적 없음 — 답글도 댓글과 동일 규칙
  if v_author <> v_uid and v_len >= 5
     and not exists (
       select 1 from public.comment_awards w
       where w.user_id = v_uid and w.diary_id = p_diary_id
     )
  then
    select * into v_claim from public.claim_mission('comment_give', 1);
    v_awarded := coalesce(v_claim.awarded, 0);
    if v_awarded > 0 then
      insert into public.comment_awards (user_id, diary_id) values (v_uid, p_diary_id)
      on conflict do nothing;
    end if;
  end if;

  return query select v_id, v_awarded, ''::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_friend(p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_n integer;
begin
  if v_me is null then return false; end if;
  delete from public.friendships
    where (requester_id = v_me and addressee_id = p_user_id)
       or (requester_id = p_user_id and addressee_id = v_me);
  get diagnostics v_n = row_count;
  return v_n > 0;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_friend(p_user_id uuid)
 RETURNS TABLE(status text, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
begin
  if v_me is null then return query select 'login', '로그인이 필요해요'; return; end if;
  if p_user_id is null or p_user_id = v_me then return query select 'self', '나에게는 신청할 수 없어요'; return; end if;
  if not exists (select 1 from auth.users u where u.id = p_user_id) then
    return query select 'none', '없는 사람이에요'; return;
  end if;

  if public.are_friends(v_me, p_user_id) then
    return query select 'friends', '이미 친구예요'; return;
  end if;

  if exists (select 1 from public.friendships f where f.requester_id = p_user_id and f.addressee_id = v_me and f.status = 'pending') then
    update public.friendships set status = 'accepted', responded_at = now()
      where requester_id = p_user_id and addressee_id = v_me;
    return query select 'friends', '친구가 됐어요'; return;
  end if;

  insert into public.friendships (requester_id, addressee_id) values (v_me, p_user_id)
    on conflict (requester_id, addressee_id) do nothing;
  return query select 'requested', '친구 신청을 보냈어요';
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_friend(p_user_id uuid, p_accept boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid := auth.uid();
  v_n integer;
begin
  if v_me is null then return false; end if;
  if p_accept then
    update public.friendships set status = 'accepted', responded_at = now()
      where requester_id = p_user_id and addressee_id = v_me and status = 'pending';
  else
    delete from public.friendships
      where requester_id = p_user_id and addressee_id = v_me and status = 'pending';
  end if;
  get diagnostics v_n = row_count;
  return v_n > 0;
end;
$function$
